# Fala, Transcrição e IA — lote L15, segunda leva
TG="x"
Q = []
TAILS=[" Essa seria a posição predominante na literatura técnica da área.",
 " Trata-se de entendimento consolidado na literatura técnica contemporânea.",
 " Tal conclusão decorreria, segundo esse entendimento, das características da tecnologia descrita.",
 " Essa seria a leitura mais aceita entre os estudiosos do tema."]
SHORT=[" Isso é consenso na área."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o entendimento usual."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.92*len(C) and gap > 14: return E+SHORT[i%len(SHORT)]
    return E
FD={"tipo":"doutrina","ref":"literatura técnica de ASR e IA; LGPD; Lei 9.610/1998","versao":"conhecimento do autor","conferida":"conhecimento"}
FJ={"tipo":"jurisprudencia","ref":"jurisprudência","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag, jur=False, lei=False):
    ex = {}
    if lei: ex["fonte"]={"tipo":"lei","ref":"Lei 13.709/2018; Lei 9.610/1998","versao":"vigente","conferida":"conhecimento"}
    elif jur: ex["fonte"]=FJ; ex["risco"]=["jurisprudencia_conhecimento"]
    else: ex["fonte"]=FD; ex["risco"]=["doutrina_conhecimento"]
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n={}
def G(i,padE,dif,C,E,com,terro,lei=False,jur=False):
    _n[i]=_n.get(i,0)+1
    P(f"F{i:02d}",[str(i+25)],"conceito_correto",padE,dif,C,E,com,terro,f"{TG}{i:02d}{_n[i]}",lei=lei,jur=jur)
# ---- 1 ASR clássico (átomo 26)
G(1,"confusao_instituto",3,"Os coeficientes MFCC são obtidos, em linhas gerais, por janelamento do sinal, transformada de Fourier, aplicação de um banco de filtros na escala mel, logaritmo e transformada discreta do cosseno.","Os coeficientes MFCC são obtidos, em linhas gerais, por janelamento do sinal, aplicação de um modelo de linguagem em n-gramas e decodificação por busca em feixe, sem emprego da escala mel.","MFCC.","mistura características acústicas e decodificação")
G(1,"confusao_instituto",3,"No ASR clássico, a hipótese escolhida é a sequência de palavras que maximiza o produto da verossimilhança acústica pela probabilidade fornecida pelo modelo de linguagem.","No ASR clássico, a hipótese escolhida é a sequência de palavras que maximiza apenas a verossimilhança acústica, pois o modelo de linguagem é usado somente para pontuar o léxico de pronúncias.","Regra de Bayes no ASR.","exclui o modelo de linguagem")
G(1,"confusao_instituto",3,"A perplexidade é medida usada para avaliar modelos de linguagem, e valores menores indicam que o modelo prevê melhor o texto de teste.","A perplexidade é medida usada para avaliar modelos acústicos, e valores maiores indicam que o modelo prevê melhor o texto de teste.","Perplexidade.","troca modelo avaliado e sentido")
G(1,"confusao_instituto",4,"O lattice produzido pelo decodificador é um grafo compacto de hipóteses alternativas, que pode ser reavaliado (rescoring) com modelo de linguagem mais forte, e o beam search reduz o custo da busca ao podar hipóteses pouco prováveis.","O lattice produzido pelo decodificador é a lista de pronúncias do léxico, e o beam search garante a obtenção da hipótese ótima global, pois examina todas as hipóteses possíveis.","Lattice; beam search.","confunde lattice e léxico; afirma busca exaustiva")
G(1,"excecao_omitida",3,"Sistemas de vocabulário fechado não reconhecem palavras fora do vocabulário (OOV), o que é problema relevante para nomes próprios de parlamentares e siglas novas.","Sistemas de vocabulário fechado reconhecem normalmente palavras fora do vocabulário, pois o modelo acústico dispensa o léxico para formar novas palavras.","OOV.","nega problema de OOV")
